    const sourceName = src => ({events: 'événements', persons: 'personnes', free: 'lignes écrites à la main', records: 'fiches à remplir (mon formulaire)'}[src] || (listMeta?.sources?.[src] ? 'liste « ' + listMeta.sources[src] + ' »' : ''));
