                d.querySelectorAll('[data-h-lrec]').forEach(b => b.addEventListener('click', () => { const t = ext.recordTemplates()[Number(b.dataset.hLrec)]; start(t, t.name === 'Liste de fiches vide' ? '' : t.name); }));
