                d.querySelectorAll('[data-h-lapp]').forEach(b => b.addEventListener('click', () => { const t = APP_LIST_TEMPLATES(listMeta.event_types)[Number(b.dataset.hLapp)]; start(t, t.name + ' (ma version)'); }));
